{
  "name": "schedule_joint_meeting",
  "request_shape": "Find a free one-hour slot next week that works for both Dana Reyes and Sam Okafor, and propose it to them.",
  "inputs": [],
  "steps": [
    {
      "id": "get_dana_availability",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Dana Reyes, next_week"
    },
    {
      "id": "get_sam_availability",
      "kind": "list",
      "source": "calendar",
      "filter": "owner: Sam Okafor, next_week"
    },
    {
      "id": "get_contacts",
      "kind": "lookup_via_agent",
      "agent": "contacts",
      "find": "Dana Reyes and Sam Okafor email addresses"
    },
    {
      "id": "compute_free_slots",
      "kind": "loop_over_items",
      "over": "get_dana_availability",
      "steps": [
        {
          "id": "check_sam_conflict",
          "kind": "check_coverage",
          "rule": "item.start_time not in get_sam_availability"
        }
      ]
    },
    {
      "id": "select_slot",
      "kind": "write",
      "instruction": "Select the first available one-hour slot from the free slots found. If none, state 'No common slot found'.",
      "max_words": 20
    },
    {
      "id": "draft_proposal",
      "kind": "write",
      "instruction": "Draft a polite email proposing the selected time slot to Dana Reyes and Sam Okafor.",
      "max_words": 100
    },
    {
      "id": "verify_proposal",
      "kind": "check_coverage",
      "rule": "draft_proposal contains the selected time slot and both names"
    }
  ],
  "output": "draft_proposal"
}
